tests/mount_from_item.rs.text:
#![cfg(any(feature = "client-retail", feature = "client-ptr"))]

use wow_ui_sim::lua_api::WowLuaEnv;

fn empty_env() -> WowLuaEnv {
    WowLuaEnv::new().expect("fresh mount-item environment")
}

#[test]
fn mount_item_empty_relation_returns_exactly_one_nil() {
    let env = empty_env();
    env.exec(
        r#"
        local query = rawget(C_MountJournal, 'GetMountFromItem')
        assert(type(query) == 'function', 'missing C_MountJournal.GetMountFromItem')
        local function miss(...)
            assert(select('#', ...) == 1, 'mount miss must return exactly ONE value')
            assert((...) == nil, 'empty supplied relation must return nil')
        end
        miss(query(6948))
        miss(query(901001))
        "#,
    )
    .expect("empty relation misses without normal catalog seeding");
}

#[test]
fn mount_item_requires_one_numeric_identity() {
    let env = empty_env();
    env.exec(
        r#"
        local query = rawget(C_MountJournal, 'GetMountFromItem')
        assert(type(query) == 'function', 'missing C_MountJournal.GetMountFromItem')
        local function numberError(...)
            local ok, message = pcall(query, ...)
            assert(not ok and type(message) == 'string', 'required numeric argument must error')
            assert(message:find('number', 1, true), 'expected number contract: ' .. message)
        end
        numberError()
        numberError(nil)
        for _, value in ipairs({false, true, '6948', 'item:6948', {}, function() end,
            coroutine.create(function() end)}) do
            numberError(value)
        end
        "#,
    )
    .expect("required number contract, not optional filter or inferred numeric domain");
}

#[test]
fn mount_item_authenticates_secret_input_before_type_or_lookup() {
    let env = empty_env();
    env.exec(
        r#"
        debug.settaintmode(true)
        assert(debug.getstacktaint() == nil, 'untainted setup')
        local query = rawget(C_MountJournal, 'GetMountFromItem')
        assert(type(query) == 'function', 'missing C_MountJournal.GetMountFromItem')
        local valid = secretwrap(6948)
        local invalid = {secretwrap('6948'), secretwrap(false), secretwrap({}), secretwrap(nil)}
        assert(issecretvalue(valid), 'VM-owned numeric secret wrapper required')
        local function miss(...)
            assert(select('#', ...) == 1, 'secret/ordinary miss arity')
            assert((...) == nil, 'empty relation miss')
        end
        local function numberError(value)
            local ok, message = pcall(query, value)
            assert(not ok and type(message) == 'string' and message:find('number', 1, true),
                'untainted invalid input must reach number validation')
            assert(not message:find('untainted caller', 1, true),
                'untainted invalid input must not fail permission gate')
        end
        miss(query(valid))
        for _, value in ipairs(invalid) do
            assert(issecretvalue(value), 'VM-owned invalid secret wrapper required')
            numberError(value)
        end
        local function denied(value)
            assert(issecretvalue(value), 'authentic wrapper before permission test')
            local ok, message = pcall(query, value)
            assert(not ok and type(message) == 'string', 'tainted secret input must fail')
            assert(message:find('untainted caller', 1, true),
                'AllowedWhenUntainted permission gate must precede type/lookup: ' .. message)
            assert(not message:find('number', 1, true), 'permission denial is not type validation')
            assert(issecretvalue(value), 'denial must retain secret wrapper')
            assert(not pcall(secretunwrap, value), 'tainted caller cannot unwrap secret')
            assert(debug.getstacktaint() == 'MountItemTest', 'denial preserves caller taint')
        end
        local function addon()
            assert(debug.getstacktaint() == 'MountItemTest', 'actual tainted closure')
            denied(valid)
            for _, value in ipairs(invalid) do denied(value) end
            miss(query(6948))
            numberError('6948')
            numberError(false)
            assert(debug.getstacktaint() == 'MountItemTest', 'ordinary query preserves taint')
        end
        debug.setobjecttaint(addon, 'MountItemTest')
        addon()
        assert(debug.getstacktaint() == nil, 'outer secure caller restored')
        assert(issecretvalue(valid), 'secure/tainted round trip retains wrapper')
        miss(query(valid))
        "#,
    )
    .expect("authentic secret permission before malformed input parsing");
}

fn fresh_mount_item_fixture_env() -> WowLuaEnv {
    let env = empty_env();
    assert!(env.state().borrow().mount_item_relations.is_empty());
    env
}

fn assert_mount_item_query(env: &WowLuaEnv, numeric_argument: &str, expected: Option<i32>) {
    let expected = expected.map_or_else(|| "nil".to_owned(), |id| id.to_string());
    let script = format!(
        r#"
        local query = rawget(C_MountJournal, 'GetMountFromItem')
        assert(type(query) == 'function', 'missing C_MountJournal.GetMountFromItem')
        local function check(...)
            assert(select('#', ...) == 1, 'mount query must return exactly ONE value')
            assert((...) == {expected}, 'wrong mount relation for {numeric_argument}')
        end
        check(query({numeric_argument}))
        "#
    );
    env.exec(&script)
        .expect("real mount-item query must match explicit fixture state");
}

#[test]
fn supplied_mount_item_mapping_needs_no_catalog_target_or_ownership() {
    let env = fresh_mount_item_fixture_env();
    {
        let mut state = env.state().borrow_mut();
        state.world.mounts.clear();
        state.mount_item_relations.insert(901001, 401);
    }
    assert!(env.state().borrow().world.mounts.is_empty());
    assert_mount_item_query(&env, "901001", Some(401));
    assert!(env.state().borrow().world.mounts.is_empty());
}

#[test]
fn supplied_mount_item_mapping_replacement_and_removal_are_live() {
    let env = fresh_mount_item_fixture_env();
    env.state()
        .borrow_mut()
        .mount_item_relations
        .insert(901001, 401);
    assert_mount_item_query(&env, "901001", Some(401));

    env.state()
        .borrow_mut()
        .mount_item_relations
        .insert(901001, 402);
    assert_mount_item_query(&env, "901001", Some(402));

    env.state()
        .borrow_mut()
        .mount_item_relations
        .remove(&901001);
    assert_mount_item_query(&env, "901001", None);
}

#[test]
fn supplied_mount_item_mapping_does_not_leak_into_independent_fresh_environment() {
    let first = fresh_mount_item_fixture_env();
    first
        .state()
        .borrow_mut()
        .mount_item_relations
        .insert(901001, 401);
    assert_mount_item_query(&first, "901001", Some(401));

    let second = fresh_mount_item_fixture_env();
    assert_mount_item_query(&second, "901001", None);
    assert_mount_item_query(&first, "901001", Some(401));
    assert!(second.state().borrow().mount_item_relations.is_empty());
}

#[test]
fn supplied_mount_item_numeric_identities_are_distinct_without_truncation_aliases() {
    let env = fresh_mount_item_fixture_env();
    env.state().borrow_mut().mount_item_relations.extend([
        (901000, 400),
        (901001, 401),
        (901002, 402),
        (i32::MIN, 403),
        (i32::MAX, 404),
        (0, 405),
    ]);
    for (argument, expected) in [
        ("901000", 400),
        ("901001", 401),
        ("901002", 402),
        ("-2147483648", 403),
        ("2147483647", 404),
        ("0", 405),
    ] {
        assert_mount_item_query(&env, argument, Some(expected));
    }
    // Populated neighbors, boundaries and zero expose truncation or saturation.
    for argument in [
        "900999",
        "901003",
        "901000.5",
        "901001.5",
        "901002.5",
        "-0.5",
        "0.5",
        "-2147483648.5",
        "2147483647.5",
        "0/0",
        "1/0",
        "-1/0",
        "-2147483649",
        "2147483648",
    ] {
        assert_mount_item_query(&env, argument, None);
    }
}

#[test]
fn supplied_mount_item_secret_identity_hits_and_recovers_across_callers() {
    let env = fresh_mount_item_fixture_env();
    env.state()
        .borrow_mut()
        .mount_item_relations
        .insert(901001, 401);
    env.exec(
        r#"
        debug.settaintmode(true)
        local query = C_MountJournal.GetMountFromItem
        local key = secretwrap(901001)
        assert(issecretvalue(key), 'authentic mapped secret key')
        local function hit(...)
            assert(select('#', ...) == 1 and (...) == 401, 'mapped identity and exact return arity')
        end
        hit(query(key))
        local function addon()
            assert(debug.getstacktaint() == 'MountMappedSecret', 'genuine tainted caller')
            local ok, message = pcall(query, key)
            assert(not ok and message:find('untainted caller', 1, true),
                'mapped secret input denied before lookup')
            assert(issecretvalue(key), 'denial retains original wrapper')
            hit(query(901001))
            assert(debug.getstacktaint() == 'MountMappedSecret', 'ordinary mapped lookup preserves taint')
        end
        debug.setobjecttaint(addon, 'MountMappedSecret')
        addon()
        assert(debug.getstacktaint() == nil and issecretvalue(key), 'secure caller and wrapper restored')
        hit(query(key))
        "#,
    )
    .expect("secure wrapped hits, tainted denial and ordinary mapped recovery");
    assert_eq!(
        env.state().borrow().mount_item_relations.get(&901001),
        Some(&401)
    );
}

tests/mount_item_player_choice.rs.text:
//! Whole cached consumer baseline; not mount-branch or native dressability proof.
#![cfg(any(feature = "client-retail", feature = "client-ptr"))]

use std::path::Path;

use wow_ui_sim::loader::{
    BlizzardAddonOverride, discover_blizzard_addon_closure_for_screen_with_overrides, load_addon,
};
use wow_ui_sim::lua_api::WowLuaEnv;
use wow_ui_sim::screen::ScreenKind;

const ROOTS: &[&str] = &[
    "Blizzard_PlayerChoice",
    "Blizzard_ItemButton",
    "Blizzard_SharedXML",
];

const ORIGINAL_ITEM_CONSUMER: &str = r#"
    local observations = {}
    local function observe(...)
        local fields = {}
        for index = 1, select('#', ...) do
            local value = select(index, ...)
            fields[index] = tostring(value)
        end
        observations[#observations + 1] = table.concat(fields, '\t')
    end
    for _, addon in ipairs({
        'Blizzard_PlayerChoice', 'Blizzard_ItemButton', 'Blizzard_SharedXML'
    }) do
        assert(C_AddOns.IsAddOnLoaded(addon), 'whole addon not loaded: ' .. addon)
    end
    assert(DoesTemplateExist('PlayerChoiceBaseOptionItemRewardTemplate'),
        'original reward XML template missing')
    local reward = CreateFrame('Button', nil, UIParent,
        'PlayerChoiceBaseOptionItemRewardTemplate')
    assert(reward:GetObjectType() == 'Button', 'original XML reward Button')
    assert(reward.itemButton, 'original XML intrinsic ItemButton child missing')

    local originalRewardMethod = PlayerChoiceBaseOptionItemRewardMixin.IsDressupReward
    local originalSetItem = ItemButtonMixin.SetItem
    assert(reward.IsDressupReward == originalRewardMethod,
        'reward must retain original vendor method identity')
    assert(reward.itemButton.SetItem == originalSetItem,
        'intrinsic ItemButton must retain original vendor SetItem identity')
    assert(reward.itemButton.SetItemInternal == ItemButtonMixin.SetItemInternal,
        'original SetItemInternal identity')
    assert(reward.itemButton.GetItemInfo == ItemButtonMixin.GetItemInfo,
        'original vendor GetItemInfo identity, not a replacement getter')

    local function provenance(fn, suffix)
        local info = debug.getinfo(fn, 'S')
        local source = info.source:gsub('\\', '/')
        observe('[mount-item consumer provenance]', info.what, source,
            info.linedefined, info.lastlinedefined)
        assert(info.what == 'Lua', 'expected cached vendor Lua method')
        assert(source:sub(-#suffix) == suffix, 'wrong vendor source: ' .. source)
    end
    local rewardSource = 'Blizzard_PlayerChoice/Blizzard_PlayerChoiceOptionBase.lua'
    local itemSource = 'Blizzard_ItemButton/Shared/ItemButtonTemplate.lua'
    provenance(reward.IsDressupReward, rewardSource)
    provenance(reward.itemButton.SetItem, itemSource)
    provenance(reward.itemButton.SetItemInternal, itemSource)
    provenance(reward.itemButton.GetItemInfo, itemSource)

    local name, link = C_Item.GetItemInfo(6948)
    assert(name == 'Hearthstone' and type(link) == 'string' and link ~= '',
        'generated real item metadata/link required')
    observe('[mount-item consumer input]', name, link)
    observe('[mount-item consumer stage]', 'original ItemButton:SetItem(6948)')
    reward.itemButton:SetItem(6948)
    assert(reward.itemButton.itemLink == link, 'real SetItem must store generated item link')
    assert(reward.itemButton:GetItemID() == 6948, 'real ItemButton item identity')
    assert(reward.itemButton.SetItem == originalSetItem,
        'SetItem identity unchanged after real setup')
    assert(reward.IsDressupReward == originalRewardMethod,
        'reward method identity unchanged before actual invocation')

    -- Observations only: no missing-API guard replaces the actual vendor call.
    observe('[mount-item consumer API observations]',
        type(C_Item.IsDressableItemByID),
        type(C_MountJournal and C_MountJournal.GetMountFromItem),
        type(C_PetJournal and C_PetJournal.GetPetInfoByItemID))
    observe('[mount-item consumer stage]', 'original reward:IsDressupReward({itemId=6948})')
    local value = reward:IsDressupReward({itemId=6948})
    assert(type(value) == 'boolean', 'actual original consumer must return a boolean')
    observe('[mount-item consumer result]', value)
    local predicate = C_Item.IsDressableItemByID
    local predicateValue = predicate(reward.itemButton.itemLink)
    observe('[mount-item consumer predicate observation]',
        type(rawget(C_Item, 'IsDressableItemByID')), type(predicateValue), predicateValue)
    local predicateSource = debug.getinfo(predicate, 'S')
    observe('[mount-item consumer predicate source]', predicateSource.what,
        predicateSource.source, predicateSource.linedefined, predicateSource.lastlinedefined)
    return value, table.concat(observations, '\n')
"#;

#[test]
fn mount_item_player_choice_real_item_consumer_returns_boolean() {
    let ui = crate::common::blizzard_addon_harness::blizzard_ui_dir();
    eprintln!("[mount-item consumer cache] {}", ui.display());
    let item = wow_ui_sim::items::get_item(6948).expect("generated real item 6948");
    assert_eq!(item.name, "Hearthstone");
    let env = crate::common::blizzard_addon_harness::new_blizzard_addon_env(&ui);
    load_player_choice_closure(&env, &ui);
    invoke_original_item_consumer(&env);
}

#[test]
fn mount_item_player_choice_original_consumer_tracks_live_supplied_relation() {
    let ui = crate::common::blizzard_addon_harness::blizzard_ui_dir();
    let env = crate::common::blizzard_addon_harness::new_blizzard_addon_env(&ui);
    load_player_choice_closure(&env, &ui);
    let baseline = invoke_original_item_consumer(&env);
    env.state()
        .borrow_mut()
        .mount_item_relations
        .insert(6948, 401);
    let mapped = invoke_original_item_consumer(&env);
    assert!(mapped, "supplied relation should produce a dress-up reward");
    assert_ne!(
        baseline, mapped,
        "actual consumer must depend on the supplied mount relation"
    );
    env.state().borrow_mut().mount_item_relations.remove(&6948);
    assert_eq!(invoke_original_item_consumer(&env), baseline);
}

fn load_player_choice_closure(env: &WowLuaEnv, ui: &Path) {
    let overrides = [BlizzardAddonOverride {
        addon: "Blizzard_PlayerChoice",
        extra_roots: &["Blizzard_ItemButton", "Blizzard_SharedXML"],
    }];
    let addons = discover_blizzard_addon_closure_for_screen_with_overrides(
        ui,
        ScreenKind::Game,
        ROOTS,
        &overrides,
    );
    eprintln!("[mount-item consumer discovered closure] {addons:?}");
    for root in ROOTS {
        assert!(
            addons.iter().any(|(name, _)| name == root),
            "whole closure root missing: {root}"
        );
    }
    for (name, toc) in addons {
        load_consumer_addon(env, &name, &toc);
    }
    assert_no_recorded_errors(env, "whole closure load");
}

fn load_consumer_addon(env: &WowLuaEnv, name: &str, toc: &Path) {
    eprintln!("[mount-item consumer load] {name}: {}", toc.display());
    let result = load_addon(&env.loader_env(), toc);
    print_recorded_errors(env, name);
    let loaded = result
        .unwrap_or_else(|error| panic!("whole closure load {name} at {}: {error}", toc.display()));
    eprintln!(
        "[mount-item consumer warnings] {name}: {:?}",
        loaded.warnings
    );
    eprintln!(
        "[mount-item consumer nil observations] {name}: {:?}",
        loaded.nil_symbol_observations
    );
    eprintln!(
        "[mount-item consumer missing requirements] {name}: {:?}",
        loaded.missing_requirements
    );
    assert!(
        loaded.warnings.is_empty(),
        "actual whole closure warnings for {name}: {:?}",
        loaded.warnings
    );
    assert_no_recorded_errors(env, name);
}

fn print_recorded_errors(env: &WowLuaEnv, boundary: &str) {
    let state = env.state().borrow();
    eprintln!(
        "[mount-item consumer Lua errors] {boundary}: {:?}",
        state.lua_errors
    );
    eprintln!(
        "[mount-item consumer Lua error records] {boundary}: {:?}",
        state.lua_error_records
    );
    eprintln!(
        "[mount-item consumer Lua error counts] {boundary}: {:?}",
        state.lua_error_counts
    );
}

fn assert_no_recorded_errors(env: &WowLuaEnv, boundary: &str) {
    assert!(
        env.state().borrow().lua_errors.is_empty(),
        "{boundary} recorded Lua errors: {:?}",
        env.state().borrow().lua_errors
    );
}

fn invoke_original_item_consumer(env: &WowLuaEnv) -> bool {
    let result = env.eval::<(bool, String)>(ORIGINAL_ITEM_CONSUMER);
    if let Ok((_, observations)) = &result {
        assert!(
            !observations.is_empty(),
            "consumer observations must be retained"
        );
        for line in observations.lines() {
            eprintln!("[mount-item consumer observation] {line}");
        }
    }
    print_recorded_errors(env, "original SetItem / IsDressupReward invocation");
    if let Err(error) = &result {
        eprintln!("[mount-item consumer original invocation error] {error}");
    }
    let (value, _) =
        result.expect("original real-item consumer call must succeed and return a boolean");
    assert_no_recorded_errors(env, "original SetItem / IsDressupReward invocation");
    value
}

tests/mount_spell_identifier.rs.text:
//! Exact291: C_MountJournal inputs, not the existing C_Spell companion.
//! Explicit aliases and strict rejection are simulator policy, not native grammar.
//! AllowedWhenTainted secret permissions remain UNMODELED; no native credit.
#![cfg(feature = "retail-12-0-5")]

use std::collections::HashMap;

use rilua::LuaApiMut;
use rilua::table_security::{wrap_host_secret_number, wrap_host_secret_string};
use wow_ui_sim::lua_api::WowLuaEnv;

const LINK: &str = "|cff71d5ff|Hspell:40192|h[Fixture Mount]|h|r";

#[derive(Debug, PartialEq)]
struct Inputs {
    relations: Vec<(u32, u32)>,
    aliases: HashMap<String, u32>,
}

fn read_inputs(env: &WowLuaEnv) -> Inputs {
    let state = env.state().borrow();
    Inputs {
        relations: state
            .world
            .mounts
            .iter()
            .map(|mount| (mount.spell_id, mount.mount_id))
            .collect(),
        aliases: state.spell_id_aliases.clone(),
    }
}

fn create_env() -> WowLuaEnv {
    let env = WowLuaEnv::new().expect("mount identifier environment");
    env.state().borrow_mut().spell_id_aliases.clear();
    env.exec(
        r#"
        function CheckMount(identifier, expected)
            assert(type(C_MountJournal) == 'table', 'actual journal namespace required')
            assert(type(C_MountJournal.GetMountFromSpell) == 'function', 'actual journal provider required')
            local result = C_MountJournal.GetMountFromSpell(identifier)
            assert(result == expected, 'spell-to-mount relation')
        end
        function RejectMount(...)
            assert(type(C_MountJournal) == 'table', 'actual journal namespace required')
            assert(type(C_MountJournal.GetMountFromSpell) == 'function', 'actual journal provider required')
            local ok, err = pcall(C_MountJournal.GetMountFromSpell, ...)
            assert(not ok and type(err) == 'string' and #err > 0, 'reject invalid input explicitly')
        end
        "#,
    )
    .expect("assertion helpers only; never replace the API");
    env
}

fn insert_alias(env: &WowLuaEnv, key: &str, spell_id: u32) {
    env.state()
        .borrow_mut()
        .spell_id_aliases
        .insert(key.to_lowercase(), spell_id);
}

fn install_host_secrets(env: &WowLuaEnv) {
    let loader = env.loader_env();
    let mut lua = loader.rilua_mut();
    rilua::table_security::register_table_security(&mut lua).expect("VM security helpers");
    for (name, number) in [
        ("MountSecretNumber", 458.0),
        ("MountSecretMissing", 999999.0),
    ] {
        let value = wrap_host_secret_number(lua.state_mut(), number);
        lua.state_mut().push(value);
        let inserted = lua.set_global_val(name, value);
        lua.state_mut().pop();
        inserted.expect("root actual secret NUMBER");
    }
    for (name, text) in [
        ("MountSecretName", "fixture mount"),
        ("MountSecretLink", LINK),
    ] {
        let value = wrap_host_secret_string(lua.state_mut(), text);
        lua.state_mut().push(value);
        let inserted = lua.set_global_val(name, value);
        lua.state_mut().pop();
        inserted.expect("root actual secret STRING");
    }
}

#[test]
fn numeric_brown_horse_spell_returns_existing_mount() {
    let env = create_env();
    env.exec("CheckMount(458, 6)").unwrap();
    assert!(read_inputs(&env).relations.contains(&(458, 6)));
}

#[test]
fn unknown_public_spell_returns_nil() {
    let env = create_env();
    env.exec("CheckMount(999999, nil)").unwrap();
    assert!(
        !read_inputs(&env)
            .relations
            .iter()
            .any(|(spell, _)| *spell == 999999)
    );
}

#[test]
fn explicit_same_id_alias_preserves_numeric_relation() {
    let env = create_env();
    insert_alias(&env, "458", 458);
    env.exec("CheckMount(458, 6); CheckMount('458', 6)")
        .unwrap();
    assert_eq!(read_inputs(&env).aliases.get("458"), Some(&458));
}

#[test]
fn numeric_alias_precedes_identity_using_another_existing_mount() {
    let env = create_env();
    insert_alias(&env, "458", 40192);
    env.exec("CheckMount(458, 107); CheckMount('458', 107); CheckMount(40192, 107)")
        .unwrap();
    assert!(read_inputs(&env).relations.contains(&(40192, 107)));
}

#[test]
fn explicit_name_alias_uses_lowercase_registry_key() {
    let env = create_env();
    insert_alias(&env, "fixture mount", 458);
    env.exec("CheckMount('FIXTURE MOUNT', 6)").unwrap();
    assert_eq!(read_inputs(&env).aliases.get("fixture mount"), Some(&458));
}

#[test]
fn numeric_string_requires_explicit_alias() {
    let env = create_env();
    env.exec("CheckMount('458', nil); CheckMount(458, 6)")
        .unwrap();
